using System.Runtime.Intrinsics;

namespace KillerPdf.Engine.Rendering;

/// <summary>Converts unprofiled process inks to the legacy renderer's display colors.</summary>
internal static class PdfDeviceCmyk
{
    internal static uint ToRgb(uint ink)
    {
        int c = (byte)ink, m = (byte)(ink >> 8), y = (byte)(ink >> 16), k = (byte)(ink >> 24);
        int ci = (c + 16) >> 5, mi = (m + 16) >> 5, yi = (y + 16) >> 5, ki = (k + 16) >> 5;
        int index = (729 * ci + 81 * mi + 9 * yi + ki) * 3;
        int red = Samples[index], green = Samples[index + 1], blue = Samples[index + 2];
        int r = red << 8, g = green << 8, b = blue << 8;
        Adjust(c, ci, 729 * 3);
        Adjust(m, mi, 81 * 3);
        Adjust(y, yi, 9 * 3);
        Adjust(k, ki, 3);
        return (uint)((byte)(Math.Max(r, 0) >> 8) << 16
            | (byte)(Math.Max(g, 0) >> 8) << 8 | (byte)(Math.Max(b, 0) >> 8));

        void Adjust(int value, int nearest, int stride)
        {
            int neighbor = value >> 5;
            if (neighbor == nearest) neighbor = nearest == 8 ? nearest - 1 : nearest + 1;
            int adjacent = index + (neighbor - nearest) * stride;
            int rate = ((value << 8) - (nearest << 13)) * (nearest - neighbor);
            r += (red - Samples[adjacent]) * rate / 32;
            g += (green - Samples[adjacent + 1]) * rate / 32;
            b += (blue - Samples[adjacent + 2]) * rate / 32;
        }
    }

    internal static uint FromRgb(byte red, byte green, byte blue)
    {
        if (!Vector256.IsHardwareAccelerated) return FromRgbScalar(red, green, blue);
        double r = red * (16d / 255), g = green * (16d / 255), b = blue * (16d / 255);
        int ri = Math.Min((int)r, 15), gi = Math.Min((int)g, 15), bi = Math.Min((int)b, 15);
        r -= ri; g -= gi; b -= bi;
        double[] samples = RgbInverseVectorTable.Samples;
        Vector256<double> sum = Vector256<double>.Zero;
        for (int dr = 0; dr < 2; dr++)
            for (int dg = 0; dg < 2; dg++)
                for (int db = 0; db < 2; db++)
                {
                    int offset = (((ri + dr) * 17 + gi + dg) * 17 + bi + db) * 4;
                    double weight = (dr == 0 ? 1 - r : r) * (dg == 0 ? 1 - g : g) * (db == 0 ? 1 - b : b);
                    Vector256<double> sample = Vector256.LoadUnsafe(ref samples[offset]);
                    sum = Vector256.Add(sum, Vector256.Multiply(sample, weight));
                }
        return (uint)((byte)Math.Round(sum.GetElement(0)) | (byte)Math.Round(sum.GetElement(1)) << 8
            | (byte)Math.Round(sum.GetElement(2)) << 16 | (byte)Math.Round(sum.GetElement(3)) << 24);
    }

    private static class RgbInverseVectorTable
    {
        // Expand once on first accelerated RGB conversion, preserving exact integer samples.
        internal static readonly double[] Samples = Array.ConvertAll(InverseSamples, value => (double)value);
    }

    private static uint FromRgbScalar(byte red, byte green, byte blue)
    {
        double r = red * (16d / 255), g = green * (16d / 255), b = blue * (16d / 255);
        int ri = Math.Min((int)r, 15), gi = Math.Min((int)g, 15), bi = Math.Min((int)b, 15);
        r -= ri; g -= gi; b -= bi;
        double cyan = 0, magenta = 0, yellow = 0, black = 0;
        for (int dr = 0; dr < 2; dr++)
            for (int dg = 0; dg < 2; dg++)
                for (int db = 0; db < 2; db++)
                {
                    int offset = (((ri + dr) * 17 + gi + dg) * 17 + bi + db) * 4;
                    double weight = (dr == 0 ? 1 - r : r) * (dg == 0 ? 1 - g : g) * (db == 0 ? 1 - b : b);
                    cyan += InverseSamples[offset] * weight;
                    magenta += InverseSamples[offset + 1] * weight;
                    yellow += InverseSamples[offset + 2] * weight;
                    black += InverseSamples[offset + 3] * weight;
                }
        return (uint)((byte)Math.Round(cyan) | (byte)Math.Round(magenta) << 8
            | (byte)Math.Round(yellow) << 16 | (byte)Math.Round(black) << 24);
    }

